import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const distDir = path.resolve(__dirname, '../dist/client');

// Read the SSR HTML generated by the local server for the root route
// This contains the correct TanStack Router hydration structure
const ssrHtmlPath = path.resolve(__dirname, '../root_ssr.html');
if (!fs.existsSync(ssrHtmlPath)) {
  console.error('root_ssr.html not found. Run: PORT=3001 node server.js && curl -s http://localhost:3001/ > root_ssr.html');
  process.exit(1);
}

let html = fs.readFileSync(ssrHtmlPath, 'utf-8');

// Remove any actual null bytes that may have been written by the SSR engine
html = html.replace(/\0/g, '');

// Replace route-specific content with a generic empty shell
// Keep the <!--$--> and <!--/$--> comments as TanStack Router expects them
html = html.replace(
  /<!--\$-->.*?<!--\/\$-->/,
  '<!--$--><div id="root"></div><!--/$-->'
);

// Clear the matches array to force a fresh client-side render
// The regex must handle both quoted and unquoted "matches" keys
html = html.replace(
  /(?:"matches"|matches):\$R\[\d+\]=\[.*?\],(?:"lastMatchId"|lastMatchId)/,
  '"matches":$R[10]=[],"lastMatchId"'
);

fs.writeFileSync(path.join(distDir, 'index.html'), html, 'utf-8');
console.log('Generated dist/client/index.html from SSR shell (null bytes removed, matches cleared)');
